// Polish and English above are complete; the other languages are basic sets (js/lang/).
Object.assign(STRINGS, EXTRA);

export let lang = "en";

export const t = (key, vars) => {
  const text = (STRINGS[lang] || STRINGS.en)[key] || STRINGS.en[key] || key;
  return vars ? text.replace(/\{(\w+)\}/g, (m, name) => (name in vars ? vars[name] : m)) : text;
};

// A task or step status in words ("done" → "gotowe"); an unknown status is shown as it is.
export const tStatus = (status) => (STRINGS.en[`st_${status}`] ? t(`st_${status}`) : status);

export function setLang(value) {
  lang = value;
}
